import java.util.Scanner;

public class JavaApplication1 {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        String lineOne = input.nextLine();
        String lineTwo = input.nextLine();
        String tempStr = lineTwo.replaceAll("_+", " ").trim();
        StringBuilder insidePart = new StringBuilder();
        int insideState = 0;
        for (char ch : tempStr.toCharArray()) {
            if (ch == '(') {
                insideState = 1;
            } else if (ch == ')') {
                insidePart.append(' ');
                insideState = 0;
            } else if (insideState == 1) {
                insidePart.append(ch);
            }
        }
        String s = lineTwo;
        int pos;
        while ((pos = s.indexOf('(')) != -1) {
            int endPos = s.indexOf(')', pos);
            if (endPos == -1) break;
            s = s.substring(0, pos) + " " + s.substring(endPos + 1);
        }
        s = s.replaceAll(" +", " ").trim();
        String insideStr = insidePart.toString().replaceAll(" +", " ").trim();
        String[] outWords = s.split(" ");
        String[] inWords = insideStr.split(" ");
        int maxLength = 0;
        for (String word : outWords) {
            if (word.length() > maxLength) {
                maxLength = word.length();
            }
        }
        if (!insideStr.isEmpty()) {
            System.out.println(maxLength + " " + inWords.length);
        } else {
            System.out.println(maxLength + " 0");
        }
    }
}
